// Check if the browser supports the getUserMedia API
const getUserMedia = (navigator.mediaDevices && navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices)) 
  || (navigator.webkitGetUserMedia && navigator.webkitGetUserMedia.bind(navigator))
  || (navigator.mozGetUserMedia && navigator.mozGetUserMedia.bind(navigator))
  || (navigator.msGetUserMedia && navigator.msGetUserMedia.bind(navigator));

if (!getUserMedia) {
  console.log("getUserMedia API not supported.");
  Script.Outputs.Failure();
  return;
}

// Create a new MediaRecorder instance
let mediaRecorder;
let chunks = [];

// Add promise variables here
let resolveDataAvailable;
let dataAvailablePromise = new Promise(resolve => {
  resolveDataAvailable = resolve;
});

// Start recording video
Script.Signals.start = async function () {
  try {
    const stream = await getUserMedia({ audio: true, video: true });
    mediaRecorder = new MediaRecorder(stream);
    console.log("Started recording...");

    // Create a new Promise for each recording
    dataAvailablePromise = new Promise(resolve => {
      resolveDataAvailable = resolve;
    });

    mediaRecorder.addEventListener('dataavailable', (event) => {
      chunks.push(event.data);
      console.log("Data available:", event.data); // Log the data chunks
      resolveDataAvailable(); // Resolve the promise
    });

    mediaRecorder.addEventListener('stop', () => {
      console.log("Stopped recording...");
    });

    mediaRecorder.start();
    Script.Outputs.videoBlob = "";
    Script.Outputs.videoUrl = ""; // Reset the video URL
    Script.Outputs.recordingStarted();
  } catch (error) {
    console.log("Error:", error); // Log the error
    Script.Outputs.error = error;
    Script.Outputs.Failure();
  }
};


// Stop recording video
Script.Signals.stop = async function() {
  if (mediaRecorder && mediaRecorder.state === 'recording') {
    mediaRecorder.stop();
    // Wait for the dataavailable event
    await dataAvailablePromise;
    const blob = new Blob(chunks, { type: 'video/webm' });
    console.log("Video blob:", blob); // Log the blob

    // Convert Blob to base64 string
    const reader = new FileReader();
    reader.readAsDataURL(blob);
    reader.onloadend = function() {
      const base64data = reader.result;
      Script.Outputs.videoBlob = base64data; // Output the base64 string

      // Create a URL for the blob
      const url = URL.createObjectURL(blob);
      Script.Outputs.videoUrl = url; // Output the URL

      Script.Outputs.success();
    }

    chunks = []; // Clear the chunks array for future recordings
    // Reset for the next recording
    dataAvailablePromise = new Promise(resolve => {
      resolveDataAvailable = resolve;
    });
  }
};

