const hasVideoAccess = Inputs.HasVideoAccess || false;
const hasMicrophoneAccess = Inputs.HasMicrophoneAccess || false;

if (!hasVideoAccess || !hasMicrophoneAccess) {
  navigator.mediaDevices.getUserMedia({ video: true, audio: true })
    .then(() => {
      Outputs.Success();
    })
    .catch((error) => {
      Outputs.Error = error;
      Outputs.Failure();
    });
} else {
  Outputs.Success();
}

