    Failure: 'signal'
};

// Function to convert base64 data to Blob
function base64ToBlob(base64, mimeType) {
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);

    // Create blob object
    const blob = new Blob([byteArray], {type: mimeType});
    return blob;
}

Script.Signals.UploadVideo = async function () {
    const videoDataUrl = Script.Inputs.VideoBlob;
    if (!videoDataUrl) return;

    const base64Data = videoDataUrl.split(',')[1]; // Extract the base64 data from the data URL
    const blob = base64ToBlob(base64Data, 'video/webm'); // Convert base64 to Blob
    const fileName = `video_${Date.now()}.webm`;
    const file = new File([blob], fileName, { type: 'video/webm' }); // Create File object

    console.log('File created:', file); // Log the created file

    try {
        const cloudFile = await Noodl.Files.upload(file, {
            onProgress: (p) => {
                console.log('Upload progress:', p.total, p.loaded); // Log the upload progress
            },
        });
        console.log('File uploaded:', cloudFile); // Log the uploaded file

        Script.Outputs.File = cloudFile;
        Script.Outputs.FileUrl = cloudFile.url; // Assuming the URL is the file path
        Script.Outputs.fileName = cloudFile.name;
        Script.Outputs.Success();
    } catch (error) {
        console.error('Upload error:', error); // Log the error
        Script.Outputs.Error = error;
        Script.Outputs.Failure();
    }
};
